


export type PaymentLinkCustomFieldRequest = { "custom_field_type": "text" | "dropdown" | "checkbox" | "textarea" | (string & {}); /** Unique custom field key. Must not have leading or trailing whitespace. Buyer answers are stored in order metadata as custom_field_<key>. minLength: 1. maxLength: 243. */ "key": string; "label": string; /** Maximum answer length for text and textarea fields, counted in Unicode code points. Defaults to 255 for text and 1000 for textarea when omitted. Each code point can occupy up to four UTF-8 bytes in the combined metadata size budget. Format: int32. minimum: 1. maximum: 4096. */ "max_length"?: number; /** Dropdown choices. Dropdown fields require at least one option. Options must not have leading or trailing whitespace. The longest option in UTF-8 bytes counts toward the combined metadata size budget. */ "options"?: Array<string>; "placeholder"?: string; /** Format: int32. */ "position"?: number; "required"?: boolean; };
